fn built(_: &Path) -> anyhow::Result<BuildOutcome> {
    Ok(BuildOutcome { success: true, files: Vec::new(), report: String::new() })
}

fn slow_agent(_: &Path, prompt: &str, cancel: &Cancel, on_line: &dyn Fn(String)) -> anyhow::Result<String> {
    let code = prompt.contains("Source files to analyze");
    let files = if code { ["src/main.rs", "src/divergence.rs", "src/scrollbar.rs", "src/ribbon/mod.rs"] } else { ["spec/index.pi", "spec/scope/divergence/index.pi", "spec/ui/components/scrollbar/index.pi", "spec/ui/components/ribbon/index.pi"] };
    on_line(r#"{"type":"system","subtype":"init","session_id":"s"}"#.into());
    for (n, file) in files.iter().enumerate() {
        if cancel.is_cancelled() { anyhow::bail!("stopped"); }
        on_line(format!(r#"{{"type":"stream_event","event":{{"type":"content_block_start","content_block":{{"type":"tool_use","id":"t{n}","name":"Read"}}}}}}"#));
        on_line(format!(r#"{{"type":"assistant","message":{{"content":[{{"type":"tool_use","id":"t{n}","input":{{"file_path":"/home/hyphyphyph/piton/repl/{file}"}}}}]}}}}"#));
        on_line(format!(r#"{{"type":"user","message":{{"content":[{{"type":"tool_result","tool_use_id":"t{n}"}}]}}}}"#));
        on_line(r#"{"type":"stream_event","event":{"type":"content_block_start","content_block":{"type":"text"}}}"#.into());
        on_line(format!(r#"{{"type":"stream_event","event":{{"type":"content_block_delta","delta":{{"type":"text_delta","text":"Looked at `{file}`: it mostly follows what's described, with a few details filled in."}}}}}}"#));
        std::thread::sleep(Duration::from_millis(300));
    }
    on_line(r#"{"type":"stream_event","event":{"type":"content_block_start","content_block":{"type":"tool_use","id":"tx","name":"Grep"}}}"#.into());
    std::thread::sleep(Duration::from_secs(120));
    anyhow::bail!("stopped")
}

fn saved(project: &Path) -> SavedReport {
    let files = divergence::list_files(project).unwrap();
    let value = |path: &str, salt: u32| {
        let mut h: u32 = salt;
        for b in path.bytes() { h = h.wrapping_mul(31).wrapping_add(b as u32); }
        (h % 100) as f32 / 100.
    };
    let reply = |mine: &[String], other: &[String], code: bool| {
        let files: Vec<String> = mine.iter().map(|path| {
            let links: Vec<String> = other.iter().filter(|o| value(&format!("{path}{o}"), 7) > 0.93).take(4)
                .map(|o| format!(r#"{{"path":"{o}","strength":{},"divergence":{},"note":"Layout and behaviour"}}"#, value(o, 3), value(o, 5) * 0.3)).collect();
            format!(r#"{{"path":"{path}","divergence":{},"definition":{},"summary":"Mostly as described, with some behaviour the spec doesn't mention.","gaps":["error states","keyboard shortcuts"],"links":[{}]}}"#,
                value(path, 1) * 0.2, 0.4 + value(path, 2) * 0.6, links.join(","))
        }).collect();
        format!(r#"{{"assessment":"{}","wellDefined":[{{"name":"Ribbon","why":"Every group, command, and tooltip is described."}},{{"name":"Scrollbar","why":"Its geometry and lock behaviour are precise."}}],"lessDefined":[{{"name":"Harness process","why":"How runs are started and stopped is left to the code."}}],"files":[{}]}}"#,
            if code { "The code follows the spec closely in the UI, while process handling and persistence are largely filled in by the implementation." } else { "The spec is thorough about layout and interaction, but thin on error handling and on what's saved where." },
            files.join(","))
    };
    let code = divergence::parse_reply(&reply(&files.sources, &files.specs, true)).unwrap();
    let spec = divergence::parse_reply(&reply(&files.specs, &files.sources, false)).unwrap();
    SavedReport { made: divergence::now() - 3 * 3600, report: divergence::merge(&files.sources, &files.specs, Some(&code), Some(&spec)), notes: Vec::new() }
}

pub fn open(main: &mut MainWindow, window: &mut Window, cx: &mut Context<MainWindow>) {
    let Ok(state) = std::env::var("SUSPENSE_SHOT") else { return };
    let project = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
